if (c == RT::Cell_handle()) {
    return Vector(0, 0, 0);
}

auto p0 = c->vertex(0)->point();
auto p1 = c->vertex(1)->point();
auto p2 = c->vertex(2)->point();
auto p3 = c->vertex(3)->point();

Point points[4] = {p0, p1, p2, p3};
Point lifted[4];

for (int i = 0; i < 4; ++i) {
    RT::Weighted_point wp = points[i];
    lifted[i] = Point(wp.point().x(), wp.point().y(), wp.point().z(), 
                     wp.weight() - wp.point().x() * wp.point().x() - 
                     wp.point().y() * wp.point().y() - 
                     wp.point().z() * wp.point().z());
}

Vector n1(lifted[1].x() - lifted[0].x(),
         lifted[1].y() - lifted[0].y(),
         lifted[1].z() - lifted[0].z());

Vector n2(lifted[2].x() - lifted[0].x(),
         lifted[2].y() - lifted[0].y(),
         lifted[2].z() - lifted[0].z());

Vector normal = CGAL::cross_product(n1, n2);
double nx = normal.x();
double ny = normal.y();
double nz = normal.z();
double nw = -nx * lifted[0].x() - ny * lifted[0].y() - nz * lifted[0].z();

RT::Geom_traits::Plane_3 plane(lifted[0], lifted[1], lifted[2]);
double a = plane.a();
double b = plane.b();
double c_param = plane.c();
double d = plane.d();

Vector velocity(-a, -b, -c_param);
velocity = velocity / std::sqrt(a*a + b*b + c_param*c_param);

return velocity;
// END_CODE

